"""Session management for multi-user web deployments."""

import asyncio
import logging
import os
import re
import time
from typing import Optional

from .app import ConsensusApp
from .config import get_data_dir

logger = logging.getLogger(__name__)

# Session defaults
DEFAULT_SESSION_TTL = 86400  # 24 hours
DEFAULT_MAX_SESSIONS = 100
CLEANUP_INTERVAL = 300  # 5 minutes

# Session ID must be a URL-safe base64 token (as generated by secrets.token_urlsafe)
_SESSION_ID_RE = re.compile(r"^[A-Za-z0-9_-]{20,64}$")


class SessionManager:
    """Manages per-user ConsensusApp instances with TTL-based expiry.

    Each session gets its own SQLite database and ConsensusApp instance.
    Sessions are identified by a cookie-based session ID.
    """

    def __init__(self, session_ttl: int = DEFAULT_SESSION_TTL,
                 max_sessions: int = DEFAULT_MAX_SESSIONS,
                 data_dir: str = "") -> None:
        self.session_ttl = session_ttl
        self.max_sessions = max_sessions
        self._sessions: dict[str, dict] = {}  # sid -> {app, last_access, db_path}
        self._lock = asyncio.Lock()
        self._cleanup_task: Optional[asyncio.Task] = None
        # Configurable via CONSENSUS_SESSION_DIR env var, constructor arg, or default
        self._data_dir = (
            data_dir
            or os.environ.get("CONSENSUS_SESSION_DIR", "")
            or os.path.join(get_data_dir(), "sessions")
        )
        os.makedirs(self._data_dir, exist_ok=True)

    def start_cleanup_loop(self) -> None:
        """Start the periodic cleanup task."""
        if self._cleanup_task is None:
            self._cleanup_task = asyncio.create_task(self._cleanup_loop())

    async def stop(self) -> None:
        """Stop cleanup and close all sessions."""
        if self._cleanup_task:
            self._cleanup_task.cancel()
            self._cleanup_task = None
        async with self._lock:
            for sid, info in self._sessions.items():
                await self._close_app(sid, info["app"])
            self._sessions.clear()

    @staticmethod
    async def _close_app(sid: str, app: ConsensusApp) -> None:
        """Release a session app's MCP providers and AI clients.

        Failures are logged and never raised: one stuck session must not
        stop the others from being closed.
        """
        try:
            await app.shutdown()
        except Exception as e:
            logger.warning("Error shutting down session %s: %s", sid[:8], e,
                           exc_info=True)
        try:
            await app.moderator.close()
        except Exception as e:
            logger.warning("Error closing moderator clients for session %s: %s",
                           sid[:8], e, exc_info=True)

    @staticmethod
    def is_valid_session_id(session_id: str) -> bool:
        """Check that session_id matches expected format (prevents path traversal)."""
        return bool(_SESSION_ID_RE.match(session_id))

    async def get_app(self, session_id: str) -> Optional[ConsensusApp]:
        """Get or create a ConsensusApp for the given session ID.

        Returns None if max sessions reached, this is a new session,
        or the session_id is invalid.
        """
        if not self.is_valid_session_id(session_id):
            logger.warning("Rejected invalid session ID: %r", session_id[:80])
            return None
        evicted: list = []
        try:
            async with self._lock:
                if session_id in self._sessions:
                    self._sessions[session_id]["last_access"] = time.time()
                    return self._sessions[session_id]["app"]

                if len(self._sessions) >= self.max_sessions:
                    # Try to evict expired sessions first
                    evicted = self._evict_expired()
                    if len(self._sessions) >= self.max_sessions:
                        return None

                db_path = os.path.join(self._data_dir, f"{session_id}.db")
                app = ConsensusApp(db_path=db_path)
                self._sessions[session_id] = {
                    "app": app,
                    "last_access": time.time(),
                    "db_path": db_path,
                }
                return app
        finally:
            await self._close_apps(evicted)

    def lookup(self, session_id: str, touch: bool = True
               ) -> Optional[ConsensusApp]:
        """The app for *session_id* unless evicted, else ``None``; never creates.

        An expired session the cleanup has not evicted yet is still returned
        (and ``touch=True`` renews it).

        For routes that cannot set the session cookie (#132): a session they
        created would be orphaned. ``touch=False`` checks liveness without
        extending the TTL (the SSE stream's keepalive check, #135).
        """
        info = self._sessions.get(session_id)
        if info is None:
            return None
        if touch:
            info["last_access"] = time.time()
        return info["app"]

    @property
    def active_count(self) -> int:
        """Number of active sessions."""
        return len(self._sessions)

    def _evict_expired(self) -> list[tuple[str, ConsensusApp]]:
        """Remove expired sessions and their databases (call under lock).

        Returns the evicted ``(sid, app)`` pairs; the caller passes them to
        ``_close_apps`` after releasing the lock, because closing an MCP
        subprocess can take seconds and every request waits on this lock.
        The database goes now, under the lock, so a returning user cannot
        reopen a file that is being deleted.
        """
        now = time.time()
        expired = [
            sid for sid, info in self._sessions.items()
            if now - info["last_access"] > self.session_ttl
        ]
        evicted = []
        for sid in expired:
            info = self._sessions.pop(sid)
            evicted.append((sid, info["app"]))
            try:
                info["app"].db.conn.close()
            except Exception as e:
                logger.warning("Error closing session DB %s: %s", sid[:8], e)
            for suffix in ("", "-wal", "-shm"):
                path = info["db_path"] + suffix
                try:
                    if os.path.exists(path):
                        os.remove(path)
                except OSError as e:
                    logger.warning("Failed to remove session DB file %s%s: %s",
                                   sid[:8], suffix, e)
        if expired:
            logger.info("Evicted %d expired sessions", len(expired))
        return evicted

    async def _close_apps(self, evicted: list[tuple[str, ConsensusApp]]
                          ) -> None:
        """Release evicted apps' MCP subprocesses and httpx clients."""
        for sid, app in evicted:
            await self._close_app(sid, app)

    async def _cleanup_loop(self) -> None:
        """Periodically evict expired sessions."""
        try:
            while True:
                await asyncio.sleep(CLEANUP_INTERVAL)
                async with self._lock:
                    evicted = self._evict_expired()
                await self._close_apps(evicted)
        except asyncio.CancelledError:
            pass
